CREATE TABLE chat(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),at TEXT NOT NULL,question TEXT NOT NULL,answer TEXT NOT NULL,tools TEXT NOT NULL);
CREATE TABLE ai_usage(user_id INTEGER NOT NULL REFERENCES users(id),month TEXT NOT NULL,tokens INTEGER NOT NULL,PRIMARY KEY(user_id,month));
CREATE TABLE proposals(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE notices(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),event TEXT NOT NULL,at TEXT NOT NULL,title TEXT NOT NULL,seen INTEGER NOT NULL DEFAULT 0,UNIQUE(user_id,event));
